<form class="vr-module-card" method="post" action="<?= e(app_url('/admin/blog/save')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($post['id']??0) ?>">
<div class="vr-module-grid"><label>Başlık<input name="title" maxlength="220" required value="<?= e($post['title']??'') ?>"></label><label>URL kısa adı<input name="slug" maxlength="190" required value="<?= e($post['slug']??'') ?>"></label><label class="wide">Kısa açıklama<textarea name="excerpt" maxlength="1500" rows="3"><?= e($post['excerpt']??'') ?></textarea></label><label class="wide">Kapak görseli URL'si<input name="featured_image" maxlength="500" value="<?= e($post['featured_image']??'') ?>" placeholder="/uploads/blog/ornek.jpg veya https://..."></label><label class="wide">Yazı içeriği<textarea name="content" required><?= e($post['content']??'') ?></textarea></label><label>Durum<select name="status"><option value="draft" <?= ($post['status']??'draft')==='draft'?'selected':'' ?>>Taslak</option><option value="published" <?= ($post['status']??'')==='published'?'selected':'' ?>>Yayında</option></select></label></div><p><button class="btn" type="submit">Kaydet</button></p></form>
<?php else: ?>
<div class="vr-module-head"><div><h1>Blog yönetimi</h1><p>Yazıları buradan oluşturun; yayınlananlar site widget'larına bağlanır.</p></div><a class="btn" href="<?= e(app_url('/admin/blog/new')) ?>">+ Yeni yazı</a></div>
<div class="vr-module-card"><table><thead><tr><th>Başlık</th><th>URL</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($posts as $item): ?><tr><td><strong><?= e($item['title']) ?></strong><div class="muted"><?= e((string)($item['published_at']??'')) ?></div></td><td>/blog/<?= e($item['slug']) ?></td><td><?= $item['status']==='published'?'Yayında':'Taslak' ?></td><td><div class="actions"><a class="btn btn-light" href="<?= e(app_url('/admin/blog/'.(int)$item['id'])) ?>">Düzenle</a><form method="post" action="<?= e(app_url('/admin/blog/delete')) ?>" onsubmit="return confirm('Bu yazı silinsin mi?')"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn btn-light" type="submit">Sil</button></form></div></td></tr><?php endforeach; ?><?php if(!$posts): ?><tr><td colspan="4">Henüz blog yazısı yok.</td></tr><?php endif; ?></tbody></table></div>
<?php endif; ?></div>